#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        SpecificEntropy::new(v, SpecificEntropyUnit::JoulePerKilogramKelvin),
        SpecificEntropy::from_joules_per_kilogram_kelvin(v)
    );
    assert_eq!(
        SpecificEntropy::from_base(v).convert_to(SpecificEntropyUnit::JoulePerKilogramKelvin),
        SpecificEntropy::from_base(v).as_joules_per_kilogram_kelvin()
    );
    assert_eq!(
        SpecificEntropy::new(v, SpecificEntropyUnit::KilojoulePerKilogramKelvin),
        SpecificEntropy::from_kilojoules_per_kilogram_kelvin(v)
    );
    assert_eq!(
        SpecificEntropy::from_base(v).convert_to(SpecificEntropyUnit::KilojoulePerKilogramKelvin),
        SpecificEntropy::from_base(v).as_kilojoules_per_kilogram_kelvin()
    );
    assert_eq!(
        SpecificEntropy::new(v, SpecificEntropyUnit::MegajoulePerKilogramKelvin),
        SpecificEntropy::from_megajoules_per_kilogram_kelvin(v)
    );
    assert_eq!(
        SpecificEntropy::from_base(v).convert_to(SpecificEntropyUnit::MegajoulePerKilogramKelvin),
        SpecificEntropy::from_base(v).as_megajoules_per_kilogram_kelvin()
    );
    assert_eq!(
        SpecificEntropy::new(v, SpecificEntropyUnit::JoulePerKilogramDegreeCelsius),
        SpecificEntropy::from_joules_per_kilogram_degree_celsius(v)
    );
    assert_eq!(
        SpecificEntropy::from_base(v)
            .convert_to(SpecificEntropyUnit::JoulePerKilogramDegreeCelsius),
        SpecificEntropy::from_base(v).as_joules_per_kilogram_degree_celsius()
    );
    assert_eq!(
        SpecificEntropy::new(v, SpecificEntropyUnit::KilojoulePerKilogramDegreeCelsius),
        SpecificEntropy::from_kilojoules_per_kilogram_degree_celsius(v)
    );
    assert_eq!(
        SpecificEntropy::from_base(v)
            .convert_to(SpecificEntropyUnit::KilojoulePerKilogramDegreeCelsius),
        SpecificEntropy::from_base(v).as_kilojoules_per_kilogram_degree_celsius()
    );
    assert_eq!(
        SpecificEntropy::new(v, SpecificEntropyUnit::MegajoulePerKilogramDegreeCelsius),
        SpecificEntropy::from_megajoules_per_kilogram_degree_celsius(v)
    );
    assert_eq!(
        SpecificEntropy::from_base(v)
            .convert_to(SpecificEntropyUnit::MegajoulePerKilogramDegreeCelsius),
        SpecificEntropy::from_base(v).as_megajoules_per_kilogram_degree_celsius()
    );
    assert_eq!(
        SpecificEntropy::new(v, SpecificEntropyUnit::CaloriePerGramKelvin),
        SpecificEntropy::from_calories_per_gram_kelvin(v)
    );
    assert_eq!(
        SpecificEntropy::from_base(v).convert_to(SpecificEntropyUnit::CaloriePerGramKelvin),
        SpecificEntropy::from_base(v).as_calories_per_gram_kelvin()
    );
    assert_eq!(
        SpecificEntropy::new(v, SpecificEntropyUnit::KilocaloriePerGramKelvin),
        SpecificEntropy::from_kilocalories_per_gram_kelvin(v)
    );
    assert_eq!(
        SpecificEntropy::from_base(v).convert_to(SpecificEntropyUnit::KilocaloriePerGramKelvin),
        SpecificEntropy::from_base(v).as_kilocalories_per_gram_kelvin()
    );
    assert_eq!(
        SpecificEntropy::new(v, SpecificEntropyUnit::BtuPerPoundFahrenheit),
        SpecificEntropy::from_btus_per_pound_fahrenheit(v)
    );
    assert_eq!(
        SpecificEntropy::from_base(v).convert_to(SpecificEntropyUnit::BtuPerPoundFahrenheit),
        SpecificEntropy::from_base(v).as_btus_per_pound_fahrenheit()
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "J/kg·K".parse::<SpecificEntropyUnit>(),
        Ok(SpecificEntropyUnit::JoulePerKilogramKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "J/kg·K").parse::<SpecificEntropy>(),
        Ok(SpecificEntropy::new(
            2.5,
            SpecificEntropyUnit::JoulePerKilogramKelvin
        ))
    );
    assert_eq!(
        "kJ/kg·K".parse::<SpecificEntropyUnit>(),
        Ok(SpecificEntropyUnit::KilojoulePerKilogramKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "kJ/kg·K").parse::<SpecificEntropy>(),
        Ok(SpecificEntropy::new(
            2.5,
            SpecificEntropyUnit::KilojoulePerKilogramKelvin
        ))
    );
    assert_eq!(
        "MJ/kg·K".parse::<SpecificEntropyUnit>(),
        Ok(SpecificEntropyUnit::MegajoulePerKilogramKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "MJ/kg·K").parse::<SpecificEntropy>(),
        Ok(SpecificEntropy::new(
            2.5,
            SpecificEntropyUnit::MegajoulePerKilogramKelvin
        ))
    );
    assert_eq!(
        "J/kg·°C".parse::<SpecificEntropyUnit>(),
        Ok(SpecificEntropyUnit::JoulePerKilogramDegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "J/kg·°C").parse::<SpecificEntropy>(),
        Ok(SpecificEntropy::new(
            2.5,
            SpecificEntropyUnit::JoulePerKilogramDegreeCelsius
        ))
    );
    assert_eq!(
        "kJ/kg·°C".parse::<SpecificEntropyUnit>(),
        Ok(SpecificEntropyUnit::KilojoulePerKilogramDegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "kJ/kg·°C").parse::<SpecificEntropy>(),
        Ok(SpecificEntropy::new(
            2.5,
            SpecificEntropyUnit::KilojoulePerKilogramDegreeCelsius
        ))
    );
    assert_eq!(
        "MJ/kg·°C".parse::<SpecificEntropyUnit>(),
        Ok(SpecificEntropyUnit::MegajoulePerKilogramDegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "MJ/kg·°C").parse::<SpecificEntropy>(),
        Ok(SpecificEntropy::new(
            2.5,
            SpecificEntropyUnit::MegajoulePerKilogramDegreeCelsius
        ))
    );
    assert_eq!(
        "cal/g·K".parse::<SpecificEntropyUnit>(),
        Ok(SpecificEntropyUnit::CaloriePerGramKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "cal/g·K").parse::<SpecificEntropy>(),
        Ok(SpecificEntropy::new(
            2.5,
            SpecificEntropyUnit::CaloriePerGramKelvin
        ))
    );
    assert_eq!(
        "kcal/g·K".parse::<SpecificEntropyUnit>(),
        Ok(SpecificEntropyUnit::KilocaloriePerGramKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "kcal/g·K").parse::<SpecificEntropy>(),
        Ok(SpecificEntropy::new(
            2.5,
            SpecificEntropyUnit::KilocaloriePerGramKelvin
        ))
    );
    assert_eq!(
        "BTU/(lb·°F)".parse::<SpecificEntropyUnit>(),
        Ok(SpecificEntropyUnit::BtuPerPoundFahrenheit)
    );
    assert_eq!(
        format!("2.5 {}", "BTU/(lb·°F)").parse::<SpecificEntropy>(),
        Ok(SpecificEntropy::new(
            2.5,
            SpecificEntropyUnit::BtuPerPoundFahrenheit
        ))
    );
    assert_eq!(
        "BTU/(lbm·°F)".parse::<SpecificEntropyUnit>(),
        Ok(SpecificEntropyUnit::BtuPerPoundFahrenheit)
    );
    assert_eq!(
        format!("2.5 {}", "BTU/(lbm·°F)").parse::<SpecificEntropy>(),
        Ok(SpecificEntropy::new(
            2.5,
            SpecificEntropyUnit::BtuPerPoundFahrenheit
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<SpecificEntropy>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = SpecificEntropy::from_base(6.0);
    let b = SpecificEntropy::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = SpecificEntropy::<i64>::from_base(7);
    let b = SpecificEntropy::<i64>::from_base(2);
    assert_eq!(a + b, SpecificEntropy::from_base(9));
    assert_eq!(a % b, SpecificEntropy::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<SpecificEntropy<i64>>(),
        SpecificEntropy::from_base(9)
    );
}
